\diagram{\begin{tikzcd}[ampersand replacement=\&,column sep=9em,row sep=10em]
\begin{gathered}\mathrm{I}_{10}\ (\text{pentagonal})\\
\figure{\usebox{180}}\\
\text{12 pentagonal structures on }K\\
\{\sigma,\sigma^{-1}\}\in\unsure{\mathbb P}_2(\unsure{\mathrm{Circ}}(K))\\
G\simeq\mathbb D_5\\
\widetilde G\simeq\mathbb D_5\times\{1,\sigma\}\end{gathered}\&\begin{gathered}\mathrm I_6\ (\text{bitetrahedral})\\
\figure{\usebox{181}}\\
\text{20 structures }K=J\amalg\omega\\
\text{with }\omega\xrightarrow{\sim}\underline\omega(J)\\
G\simeq\unsure{\mathfrak S}_J\simeq\unsure{\mathfrak S}_3\\
\widetilde G\simeq\unsure{\mathfrak S}_3\times\{1,\sigma\}\end{gathered} \arrow[r,"{3\quad f_{B,s}\quad2}","{(B\in\mathrm{Bit\acute et}(K),\ s\in T(B)=J)}"'] \& \begin{gathered}\mathrm I_4\ (\text{pyramidal})\\
\figure{\usebox{182}}\\
\text{30 oriented square structures}\\
K\simeq\{P\}\amalg I\\
I\ \text{structure of an \uline{oriented} square}\ (Q,\omega)=\vec Q\\
I=\coprod_{\alpha\in\delta}\alpha\qquad\delta=\text{set of diagonals }\alpha\\
\omega\in\unsure{\delta|J}\wedge\bigwedge_{\alpha\in\delta}\alpha\\
G=\widetilde G=\mathbb Z/4\mathbb Z\end{gathered} \arrow[dl,bend right=10,pos=.27,"{4\quad f_{\vec Q,\unsure{\omega},a}\quad2}","{(Q=\overrightarrow{\mathrm{Carr}}(K),\ a\in\unsure{\Lambda}(Q))}"'] \\
\begin{gathered}\mathrm{II}_2\ (\text{right square-triangle})\\
\figure{\usebox{183}}\\
\text{2 reference vertices}\quad\deleted{\text{\unsure{frames}}}\\
\text{60 structures ``pentagon}\\
\text{with vertex'' on }K\\
\text{that is, }K\simeq \unsure{J|B}\amalg\omega,\ \text{with }\omega\hookrightarrow J\\
\text{that is, }P\in J\text{ and }\omega\xrightarrow{\sim}\omega'=\unsure{J|B}\setminus\{P\}\\
G\simeq\mathbb Z/2\mathbb Z\\
\widetilde G\simeq\mathbb Z/2\mathbb Z\times\{1,\sigma\}\end{gathered} \arrow[u,"{1\quad\gamma_{\pi,s}\quad5}","{(\pi\in\mathrm{Pent}(K),\ s\in K)}"'] \arrow[r,"{1\quad\tau_{\pi,s}=\mathrm{tw}_{1/4}\quad1}"] \& \begin{gathered}\mathrm{II}'_2=\mathrm{Tw}_{1/4}\mathrm{II}_2\\
(\text{left square-triangle})\\
\text{4 vertices}\ \deleted{\text{\unsure{frames}}}\\
\deleted{\figure{\usebox{184}}}\quad\figure{\usebox{185}}\\
\text{same parameters as }\mathrm{II}_2\\
G\simeq\mathbb Z/2\mathbb Z,\ \widetilde G\simeq\mathbb Z/2\mathbb Z\times\{1,\sigma\}\end{gathered} \arrow[u,"{\unsure{\gamma^1_{\pi,s}|\gamma'_{\pi,s}}\quad3}","{\text{compatible with }\unsure{\vec Q|\vec G};\ (\pi\in\mathrm{Pent}(K),\ s\in K)}"'] \& \begin{gathered}\mathrm{II}_1\ (\text{tetrahedron-triangle})\\
\figure{\usebox{186}}\\
\text{6 reference vertices}\\
\text{120 structures \unsure{entirely|anticanonical}}\\
\text{pinned,}\\
G=\deleted{\unsure{1}}=\{1\},\quad\widetilde G=\{1,\sigma\}\\
\left[\begin{gathered}K=J\amalg\varepsilon\quad\operatorname{card}J=3,\operatorname{card}\varepsilon=2\\\omega\in\underline\omega(J)),\ r\in J\times\varepsilon\\\tau_r^0:\mathrm{II}_1(J,\varepsilon)\longrightarrow\mathrm{II}_1(u_\omega(r))\\\text{where }u_\omega=\omega\times(-1)\text{ on }J\times\varepsilon\end{gathered}\right]\end{gathered} \arrow[ul,pos=.73,"{1\quad\gamma_r^0\quad6}","{\text{compatible with }\unsure{\vec Q|\vec G}}"'] \arrow[loop right,"{\tau_r^0=\mathrm{tw}_{1/6}}"] \\
\begin{gathered}\mathrm{III}_2\ (\text{right triple triangle})\\
\figure{\usebox{187}}\\
\text{2+2 reference vertices}\\
\text{60 structures ``pentagon with}\\
\text{vertex'' on }K,\\
G=\mathbb Z/2\mathbb Z,\widetilde G\simeq\mathbb Z/2\mathbb Z\times\{1,\sigma\}\end{gathered} \arrow[u,"{2\quad\gamma_{\pi,\rho}\quad2}","{(\pi\in\mathrm{Pent}(K),\rho\in\mathrm{Rep}\,\pi)}"'] \arrow[r,"{\unsure{\tau_{\pi,\omega}}}","{2\quad\tau_{\pi,\rho}=\mathrm{tw}_{\unsure{1/4|1/3}}\quad\unsure{1|2}}"'] \& \begin{gathered}\mathrm{III}_1\ (\text{semi-left triple triangle})\\
\figure{\usebox{188}}\quad=\quad\figure{\usebox{189}}\\
\text{2+4 reference vertices}\\
\text{120 pinned structures}\\
G=1,\widetilde G=\{1,\sigma\}\end{gathered} \arrow[u,"{1\quad\gamma_r^1\quad2}"] \arrow[ur,"{3\quad\gamma^{1'}_r\quad3}","{(r\in\mathrm{Rep}(K))}"'] \arrow[r,"{1\quad\tau'_r\quad2}"] \& \begin{gathered}\mathrm{III}'_2\ (\text{left triple triangle})\\
\figure{\usebox{190}}\quad\simeq\quad\figure{\usebox{191}}\\
\text{4+4 reference vertices}\\
\text{60 oriented square structures with}\\
\text{codiagonals, }K=\{P\}\amalg I,\\
I\ \text{equipped with a \inserted{structure} of a square in codiagonals }\delta=\{\{\alpha,\beta\},\{\alpha',\beta'\}\}\\
\text{that is, with a frame of }\unsure{\mathfrak X}(I)\\
G=\mathbb Z/2\mathbb Z\deleted{\unsure{*}},\quad\widetilde G\simeq\mathbb Z/2\mathbb Z\times\mathbb Z/2\mathbb Z\simeq\mathbb Z/2\mathbb Z\times\{1,\sigma\}\end{gathered} \arrow[uu,bend right=70,"{1\quad\unsure{\gamma_r^{21}|\gamma_r^{2'}}\quad2}"] \arrow[ul,bend left=40,"{2\quad\gamma_r^2\quad2}"']
\end{tikzcd}}

